function frac(m){if(m>=18)return 1;if(m<=2)return .25*Math.max(.3,m/2);for(var i=1;i<G.length;i++)if(m<=G[i][0]){var a=G[i-1],b=G[i];return a[1]+(b[1]-a[1])*(m-a[0])/(b[0]-a[0])}return 1}
function fac(m,ster,act){var ad=ster?1.6:1.8,f;if(m<=3)f=3;else if(m<=6)f=3-(m-3)/3;else if(m<=12)f=2-(2-ad)*(m-6)/6;else if(m<96)f=ad;else f=ster?1.3:1.4;return m<4?f*Math.min(act,1.1):f*act}
