function shrink(f){return new Promise(function(ok){var r=new FileReader();r.onload=function(){var im=new Image();im.onload=function(){var k=Math.min(1,1600/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext("2d").drawImage(im,0,0,c.width,c.height);ok(c.toDataURL("image/jpeg",.85))};im.onerror=function(){ok(null)};im.src=r.result};r.onerror=function(){ok(null)};r.readAsDataURL(f)})}
function foto(b){var i=document.createElement("input");i.type="file";i.accept="image/*";i.multiple=true;i.onchange=function(){var fs=[].slice.call(i.files,0,2);if(!fs.length)return;var lab=b.innerHTML;b.disabled=true;b.textContent=TX.reading;$("pp-err").textContent="";
  Promise.all(fs.map(shrink)).then(function(parts){parts=parts.filter(Boolean);return fetch(API,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({parts:parts})})}).then(function(r){return r.json()}).then(function(j){
    b.disabled=false;b.innerHTML=lab;if(!j||!j.ok){$("pp-err").textContent=j&&j.limit?TX.limit:TX.fail;return}addForm("foto");if(j.p!=null||j.ca!=null)["p","f","fi","a","u","ca","ph"].forEach(function(q){var e=$("pp-"+q);if(e&&j[q]!=null)e.value=dec(j[q])});
    $("pp-nm").value=((j.brand||"")+" "+(j.name||"")).trim();if(j.kcal)$("pp-k").value=j.kcal;$("pp-add").setAttribute("data-foto","1");MYADD=j.add||null;
    var e=$("pp-err");e.className="pp-ok pp-okv";e.textContent=j.kcal?TX.how[j.how]||"":TX.how.none
  }).catch(function(){b.disabled=false;b.innerHTML=lab;$("pp-err").textContent=TX.limit})};i.click()}
box.classList.add("pp-nuovo");
