 if(b.getAttribute("data-k")){var k=b.getAttribute("data-k");S[k]=+b.getAttribute("data-v");keep();if(k==="meals"||k==="bcs"||k==="act"){[].forEach.call(box.querySelectorAll('[data-k="'+k+'"]'),function(y){y.classList.toggle("on",y===b)});draw()}else build();return}
 if(b.getAttribute("data-sx")){var ns=b.getAttribute("data-sx");if(ns!==S.sex){var old=TX.sizes.filter(function(z){return num(S.adult)===szKg(z[0])})[0];S.sex=ns;if(old)S.adult=String(szKg(old[0]));keep();build()}return}
